import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const SetupProfile = () => {
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const fileInputRef = useRef(null);
  const { user, updateUser } = useAuth();
  const navigate = useNavigate();

  const handleFileSelect = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setFile(selectedFile);
      setPreview(URL.createObjectURL(selectedFile));
    }
  };

  const handleUpload = async () => {
    if (!file) {
      navigate('/');
      return;
    }

    setLoading(true);
    const formData = new FormData();
    formData.append('profilePicture', file);

    try {
      const res = await axios.post('http://localhost:5000/api/users/profile-picture', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      updateUser(res.data);
      navigate('/');
    } catch (err) {
      alert('Failed to upload profile picture');
      setLoading(false);
    }
  };

  const handleSkip = () => {
    navigate('/');
  };

  return (
    <div className="setup-container">
      <div className="setup-card">
        <h1>📸 Set Up Your Profile</h1>
        <p>Add a profile picture to get started</p>
        
        <div className="setup-avatar-wrapper" onClick={() => fileInputRef.current.click()}>
          {preview ? (
            <img src={preview} alt="Preview" className="setup-avatar" />
          ) : (
            <div className="setup-avatar-placeholder">
              <span>+</span>
              <p>Add Photo</p>
            </div>
          )}
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileSelect}
            accept="image/*"
            style={{ display: 'none' }}
          />
        </div>

        <div className="setup-buttons">
          <button className="skip-btn" onClick={handleSkip}>
            Skip for now
          </button>
          <button 
            className="upload-btn" 
            onClick={handleUpload}
            disabled={loading}
          >
            {loading ? 'Uploading...' : '✅ Continue'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default SetupProfile;
